// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    BankCaller caller;

    function setUp() public {
        c = new ModifierEntrancy();
        caller = new BankCaller();
    }

    function testFuzz_property(uint256 seed) public {
        // seed is an admissible arbitrary fuzz input; any value must obey the rule
        vm.assume(seed >= 0);

        // drive c through airDrop via a Bank-compatible caller (supportsToken requires msg.sender to be a Bank)
        caller.callAirDrop(c);

        // general rule: one successful airDrop from a zero-balance caller credits EXACTLY 20 tokens
        assertTrue(c.tokenBalance(address(caller)) == 20, "airDrop must credit exactly 20");
    }
}

contract BankCaller is Bank {
    function callAirDrop(ModifierEntrancy c) external {
        c.airDrop();
    }
}
